(async () => {
  // 模擬點按鈕，但 navigator.clipboard 在 headless 可能會壞，所以直接測 loadPrompt
  try {
    const txt = await loadPrompt();
    return {
      viewport: {w: window.innerWidth, h: window.innerHeight},
      promptLength: txt.length,
      promptOK: txt.includes('開工宣言') && txt.includes('CC BY-ND'),
      btnW: document.querySelector('#copyBtn').getBoundingClientRect().width,
      heroH1Size: getComputedStyle(document.querySelector('.hero h1')).fontSize,
      creedCols: getComputedStyle(document.querySelector('.creed')).gridTemplateColumns
    };
  } catch (e) {
    return {error: e.message};
  }
})()

